function showSalesReview(items,latest){modal("Nuevas ventas encontradas",items.length?`<form class="form" id="import-reviewed-sales-form"><p class="form-help">Se encontraron <b>${items.length}</b> ventas posteriores al corte ${latest?formatDate(latest):"inicial"}. Desmarca las que no quieras importar.</p><div class="sales-review-list">${items.map(item=>{const exists=state.clients.some(c=>cleanRuc(c.ruc)===item.ruc);return `<label class="sales-review-row"><input type="checkbox" name="saleKey" value="${esc(item.key)}" checked><span><b>${formatDate(item.fecha)} · ${esc(item.razon)}</b><small>RUC ${esc(item.ruc)} · ${exists?"Cliente existente":"Cliente nuevo"} · ${item.estadoPago==="pendiente"?"Pendiente":"Pagado"}</small></span></label>`;}).join("")}</div><button>Importar ventas seleccionadas</button></form>`:`<div class="sales-empty">No se encontraron ventas nuevas respecto de las que ya existen en el sistema.</div><button class="primary dark" data-action="close-import">Aceptar</button>`,true);}
