function contactDetails(c){const contacts=Array.isArray(c.contactos)&&c.contactos.length?c.contactos:[{telefono:c.contacto,correo:c.correo}];return `<div class="contact-list">${contacts.map(contact=>`<span><b>${esc(`${contact.nombre||""} ${contact.apellido||""}`.trim())||"Contacto"}</b><small>${esc(contact.telefono||"")}${contact.telefono&&contact.correo?" · ":""}${esc(contact.correo||"")}</small></span>`).join("")}</div>`;}
function inventorySeriesRow(value,c,sales){const sale=sales.find(item=>(item.series||[]).some(series=>normalize(series)===normalize(value)));return `<div class="inventory-series-row"><b>${esc(value)}</b>${sale?`<span class="series-sale-status linked">${formatDate(sale.fecha)} · ${esc(sale.detalle)||"Venta asociada"}</span>`:`<span class="series-sale-status free">Sin venta</span><button data-action="assign-existing-series" data-client="${c.id}" data-series="${esc(value)}">Asignar a venta</button><button class="remove-series-btn" title="Quitar serie" data-action="delete-client-series" data-id="${c.id}" data-series="${esc(value)}">×</button>`}</div>`;}
function saleRow(sale,c){const paid=sale.estadoPago==="pagado",series=Array.isArray(sale.series)?sale.series:[];return `<article class="sale-row"><div class="sale-main"><div><span class="label">FECHA DE VENTA</span><b>${formatDate(sale.fecha)}</b></div><div><span class="label">DETALLE</span><b>${esc(sale.detalle)||"Venta de equipos"}</b></div><span class="payment-badge ${paid?"paid":"pending"}">${paid?"Pagado":"Pendiente"}</span></div><div class="sale-series"><span class="label">SERIES DE ESTA VENTA</span><div class="series-chips">${series.map(value=>`<span class="series-chip sale"><b>${esc(value)}</b></span>`).join("")||'<span class="series-empty">Sin series asignadas</span>'}</div></div><div class="sale-controls"><button class="edit-sale-btn" data-action="edit-sale" data-client="${c.id}" data-sale="${esc(sale.id)}">Editar venta</button><button class="edit-sale-btn" data-action="copy-sale" data-client="${c.id}" data-sale="${esc(sale.id)}">Copiar venta</button><button class="delete-sale-btn" data-action="delete-sale" data-client="${c.id}" data-sale="${esc(sale.id)}">Eliminar venta</button><button class="payment-toggle ${paid?"paid":""}" data-action="toggle-sale-payment" data-client="${c.id}" data-sale="${esc(sale.id)}">${paid?"Marcar pendiente":"Marcar como pagado"}</button>${paid?`<button class="assign-series-btn" data-action="assign-sale-series" data-client="${c.id}" data-sale="${esc(sale.id)}">+ Asignar series</button>`:'<span class="sale-waiting">Confirma el pago para asignar series</span>'}</div></article>`;}
function shipmentRow(s,c,actions=false){const isImage=s.documento?.tipo?.startsWith("image/");return `<article class="shipment-row"><div class="shipment-date"><b>${formatDate(s.fecha)}</b><span>${esc(s.serie)||"Sin serie"}</span></div><div><span class="label">TRACKING</span><b>${esc(s.tracking)||"Sin tracking"}</b><small>${esc(s.nota)||""}</small></div><div><span class="label">ARCHIVO</span>${s.documento?`<button class="link-btn" data-action="open-file" data-id="${s.id}">${isImage?"🖼️":"📄"} ${esc(s.documento.nombre)}</button>`:"<span>Sin archivo</span>"}</div>${actions?`<div class="shipment-actions"><button class="edit-link" data-action="edit-shipment" data-id="${s.id}" data-client="${c.id}">Editar</button><button class="danger-link" data-action="delete-shipment" data-id="${s.id}" data-client="${c.id}">Eliminar</button></div>`:""}</article>`;}

$("#client-search").addEventListener("input",()=>{state.clientPage=1;renderClients();});
$("#calendar-search").addEventListener("input",renderCalendar);
$("#prev-month").onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);renderCalendar();};
$("#next-month").onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);renderCalendar();};
$("#today").onclick=()=>{state.month=new Date();renderCalendar();};

function render(){renderClients();renderCalendar();renderDashboard();}
function renderClients(){const q=normalize($("#client-search")?.value),filtered=state.clients.filter(c=>normalize(`${c.ruc} ${c.razon} ${c.contacto} ${clientSeries(c).join(" ")}`).includes(q)),totalPages=Math.max(1,Math.ceil(filtered.length/state.clientPageSize));state.clientPage=Math.min(Math.max(1,state.clientPage),totalPages);const start=(state.clientPage-1)*state.clientPageSize,visible=filtered.slice(start,start+state.clientPageSize),rows=visible.map(c=>{const ss=clientShipments(c.id),series=clientSeries(c),sales=clientSales(c),pending=sales.filter(sale=>sale.estadoPago!=="pagado").length;return `<tr><td data-label="RUC">${esc(c.ruc)}</td><td data-label="Razón social"><b>${esc(c.razon)}</b></td><td data-label="Contacto">${esc(c.contacto)}</td><td data-label="Series"><span class="count series-count">${series.length}</span></td><td data-label="Ventas / pago"><span class="sales-cell"><b>${sales.length} ventas</b><small class="${pending?"has-pending":""}">${pending?pending+" pendientes":"Todo pagado"}</small></span></td><td data-label="Envíos"><span class="count">${ss.length}</span></td><td data-label="Último envío">${ss[0]?formatDate(ss[0].fecha):"—"}</td><td class="row-actions"><button class="whatsapp-mini" title="Abrir WhatsApp" aria-label="Abrir WhatsApp de ${esc(c.razon)}" data-action="whatsapp" data-id="${c.id}">${whatsappIcon}</button><button class="ghost action" data-action="open-client" data-id="${c.id}">Abrir ficha →</button></td></tr>`;}).join("");$("#clients-table").innerHTML=rows||'<tr><td colspan="8" class="empty">No se encontraron clientes.</td></tr>';renderClientPagination(filtered.length,totalPages,start,visible.length);}
function renderClientPagination(total,totalPages,start,visible){const el=$("#clients-pagination");if(!el)return;const from=total?start+1:0,to=start+visible;el.innerHTML=`<div class="pagination-summary">Mostrando <b>${from}–${to}</b> de <b>${total}</b> clientes</div><div class="pagination-actions"><label>Por página <select id="client-page-size"><option value="10" ${state.clientPageSize===10?"selected":""}>10</option><option value="20" ${state.clientPageSize===20?"selected":""}>20</option><option value="50" ${state.clientPageSize===50?"selected":""}>50</option></select></label><button data-action="client-page" data-page="${state.clientPage-1}" ${state.clientPage===1?"disabled":""}>‹ Anterior</button><span>Página <b>${state.clientPage}</b> de ${totalPages}</span><button data-action="client-page" data-page="${state.clientPage+1}" ${state.clientPage===totalPages?"disabled":""}>Siguiente ›</button></div>`;}
function renderDashboard(){const now=new Date(),prefix=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;$("#stat-clients").textContent=state.clients.length;$("#stat-shipments").textContent=state.shipments.length;$("#stat-month").textContent=state.shipments.filter(s=>s.fecha.startsWith(prefix)).length;$("#stat-pdf").textContent=state.shipments.filter(s=>s.documento).length;const latest=state.shipments.slice().sort((a,b)=>b.fecha.localeCompare(a.fecha)).slice(0,5);$("#recent-list").innerHTML=latest.map(s=>{const c=clientById(s.clientId)||{};return shipmentRow(s,c);}).join("")||'<div class="empty">No hay envíos registrados.</div>';}
function matchesShipment(s,q){const c=clientById(s.clientId)||{};return normalize(`${c.ruc} ${c.razon} ${c.contacto} ${clientSeries(c).join(" ")} ${s.serie} ${s.tracking} ${s.nota}`).includes(q);}
function renderCalendar(){const y=state.month.getFullYear(),m=state.month.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),q=normalize($("#calendar-search")?.value);$("#month-label").textContent=new Intl.DateTimeFormat("es-PE",{month:"long",year:"numeric"}).format(first);let h=["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"].map(n=>`<div class="day-name">${n}</div>`).join("");for(let i=0;i<(first.getDay()+6)%7;i++)h+='<div class="day muted"></div>';for(let d=1;d<=last.getDate();d++){const key=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`,items=state.shipments.filter(s=>s.fecha===key&&matchesShipment(s,q));h+=`<div class="day ${items.length?"has-shipment":""}"><div class="num">${d}</div>${items.slice(0,3).map(s=>{const c=clientById(s.clientId)||{},label=`${c.razon||"Cliente"}${s.serie?` · ${s.serie}`:""}`;return `<button class="event" title="${esc(label)}" data-action="open-client" data-id="${c.id}">${esc(label)}</button>`;}).join("")}${items.length>3?`<div class="more">+${items.length-3} más</div>`:""}</div>`;}$("#calendar-grid").innerHTML=h;const prefix=`${y}-${String(m+1).padStart(2,"0")}`,monthItems=state.shipments.filter(s=>s.fecha.startsWith(prefix)&&matchesShipment(s,q)).sort((a,b)=>a.fecha.localeCompare(b.fecha));$("#month-shipments").innerHTML=monthItems.map(s=>{const c=clientById(s.clientId)||{};return shipmentRow(s,c);}).join("")||'<div class="empty">No hay envíos que coincidan en este mes.</div>';}
function formatDate(v){if(!v)return"—";return new Intl.DateTimeFormat("es-PE",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).format(new Date(`${v}T00:00:00Z`));}
render();
